{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C30"],
      "claim": "Trametinib, a close structural analogue with aryl amide, fluoroaromatic, and cyclopropyl features, had absolute oral bioavailability of 72.3% in patients with solid tumours, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Apalutamide, sharing fluoroaromatic amide and hydrophobic cyclopropyl-like features, showed approximately 100% absolute oral bioavailability in a phase 1 microtracer study.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Safinamide, containing an aryl ether and fluoroaromatic motif, had absolute oral bioavailability of 95.3% in healthy subjects, supporting high F for the query's ether/amide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Regorafenib, with an aryl amide/urea and fluoroaromatic structure, had absolute oral bioavailability of 83% as a solution, well above the threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Rimegepant, a complex heteroaromatic amide, had absolute bioavailability of 64% in healthy volunteers, supporting high oral absorption for the query's heteroaromatic amide system.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "LY2196044, an aryl ether/amide with fluoroaromatic and basic amine features, had estimated absolute bioavailability of 45% in humans, still clearly above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Encainide, despite first-pass metabolism, had absolute oral bioavailability of 32 ± 7% in normal subjects, above the 20% threshold and indicating that moderate metabolic liability does not imply low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "A highly polar tetracycline analogue had mean absolute bioavailability of 31.2%, the lowest among retrieved analogues, yet still above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues have absolute oral bioavailability above 20% (range ~31–100%), with most above 45%. The query shares absorption-permissive features such as aryl amide, fluoroaromatic, heteroaromatic ether, and cyclopropyl groups, supporting a high F prediction.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule itself.",
    "No retrieved analogue contains the acrylamide warhead; potential first-pass Michael-addition metabolism is not directly represented, though it is unlikely to drop F below 20% given the consistent analogue data.",
    "Some records are not explicitly absolute bioavailability or are predicted values, but the decision relies on direct absolute measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

